CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,pass_hash TEXT NOT NULL,fails INTEGER NOT NULL DEFAULT 0,lock_until INTEGER NOT NULL DEFAULT 0,token_version INTEGER NOT NULL DEFAULT 0,data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requests (id INTEGER PRIMARY KEY,from_user INTEGER NOT NULL,to_user INTEGER NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY,from_user INTEGER NOT NULL,to_user INTEGER NOT NULL,message_text TEXT NOT NULL,created_at INTEGER NOT NULL,data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY,data_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY,by_user INTEGER NOT NULL,target_user INTEGER NOT NULL,value TEXT,created_at INTEGER NOT NULL,data_json TEXT NOT NULL,UNIQUE(by_user,target_user));
CREATE TABLE IF NOT EXISTS app_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_requests_pair ON requests(from_user,to_user);
CREATE INDEX IF NOT EXISTS idx_messages_pair_time ON messages(from_user,to_user,created_at);
CREATE INDEX IF NOT EXISTS idx_feedback_by ON feedback(by_user);
CREATE TABLE IF NOT EXISTS auth_limits (bucket TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
